# External scripts are hash-authorized by the existing CSP, so regenerate only the allowlist.
config=ROOT/'vercel.json'
if config.exists():
    v=json.loads(config.read_text())
    hashes=set(re.findall(r"'((?:sha256|sha384|sha512)-[^']+)'", next(item['value'] for group in v['headers'] for item in group['headers'] if item['key']=='Content-Security-Policy')))
    for p in ROOT.rglob('*.html'):
        if '.git' in p.parts: continue
        text=p.read_text()
        for sri in re.findall(r'<script\b[^>]*\bintegrity="([^"]+)"',text): hashes.update(sri.split())
    for header in v['headers']:
        for item in header['headers']:
            if item['key']=='Content-Security-Policy':
                item['value']=re.sub(r"script-src [^;]+;",'script-src '+ ' '.join("'"+x+"'" for x in sorted(hashes))+';',item['value'])
    config.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
